on public.book_notes
for update
to authenticated
using (
  organization_id = (select organization_id from public.profiles where id = auth.uid())
  and (
    author_id = auth.uid()
    or exists (
      select 1
      from public.profiles p
      where p.id = auth.uid()
        and p.role in ('admin', 'manager')
    )
  )
)
with check (
  organization_id = (select organization_id from public.profiles where id = auth.uid())
);

